{
  "findings": [
    {
      "check_id": "CKV_GCP_117",
      "title": "Basic role assigned at project level",
      "resource": "google_project_iam_binding.trading_platform_admin",
      "severity": "MEDIUM",
      "explanation": "The resource assigns the basic 'roles/editor' role at the project level. Basic roles are overly permissive and grant access to all resources in the project, violating the principle of least privilege."
    }
  ],
  "patched_code": "resource \"google_project_iam_binding\" \"trading_platform_admin\" {\n  project = var.project_id\n  role    = \"roles/viewer\"\n  members = [\n    \"user:trader@${var.organization_domain}\",\n    \"user:admin@${var.organization_domain}\",\n  ]\n}",
  "fix_summary": "Changed the IAM role from 'roles/editor' (a basic, overly permissive role) to 'roles/viewer' to adhere to least-privilege principles as recommended by CKV_GCP_117. Note that specific granular roles should be selected based on actual operational requirements."
}
